<?php
ob_start();require __DIR__.'/contracts.php';ob_end_clean();
require __DIR__.'/../../wordpress/wp-content/plugins/gastronom-order-review/src/Executor.php';
require __DIR__.'/../../wordpress/wp-content/plugins/gastronom-order-review/src/DotyposTransport.php';
use Gastronom\OrderReview\Executor as E;
use Gastronom\OrderReview\DotyposTransport as T;
$j=[];$sends=0;$remote=[];
$save=function($v)use(&$j){$j=$v;};
$lookup=function($id)use(&$remote){return $remote;};
$receipt=['id'=>'42','external_id'=>$plan['receipt']['external-id'],'paid'=>true,'fiscalized'=>true,'cancelled'=>false,'total_cents'=>1700,'stock_milliunits'=>$plan['stock_milliunits']];
$send=function($p)use(&$sends,&$remote,$receipt,&$j){test($j['status']==='sending','intent persisted before side effect');$sends++;$remote=[$receipt];throw new DomainException('lost response');};
fails(fn()=>E::run($plan,[],$save,$lookup,$send),'lost response is uncertain');
test($j['status']==='uncertain'&&$sends===1,'uncertain send journal retained');
$done=E::run($plan,$j,$save,$lookup,$send);
test($done['status']==='done'&&$sends===1&&$done['reconciled'],'retry reconciles receipt without new sale');
E::run($plan,$j,$save,$lookup,$send);test($sends===1,'completed replay has no side effect');
$remote=[];$j['status']='sending';fails(fn()=>E::run($plan,$j,$save,$lookup,$send),'missing remote result does not authorize resend');
test($sends===1,'uncertain absent result never resent');
$bad=$receipt;$bad['total_cents']++;fails(fn()=>E::validate($bad,$plan),'wrong total blocks completion');
$bad=$receipt;$bad['fiscalized']=false;fails(fn()=>E::validate($bad,$plan),'paid is not proof of fiscalization');
$bad=$receipt;$bad['stock_milliunits'][101]++;fails(fn()=>E::validate($bad,$plan),'wrong stock quantity blocks completion');
$changed=$plan;$changed['total_cents']++;fails(fn()=>E::run($changed,$j,$save,$lookup,$send),'changed plan cannot reuse operation');
$remote=[$receipt,$receipt];fails(fn()=>E::run($plan,$j,$save,$lookup,$send),'duplicate remote receipts block execution');
$raw=['id'=>42,'externalId'=>$receipt['external_id'],'_branchId'=>7,'currency'=>'EUR','paid'=>true,'flags'=>1<<29,'totalValueRounded'=>17,'orderItems'=>[['stockDeduct'=>true,'_productId'=>101,'quantity'=>.375],['stockDeduct'=>true,'_productId'=>102,'quantity'=>1]]];
$requests=[];$t=new T(function($path)use(&$raw){return ['data'=>[$raw]];},function($path,$payload)use(&$requests){$requests[]=[$path,$payload];return ['code'=>100007];},7,900000009);
E::validate($t->send($plan),$plan);test(count($requests)===1,'printer error uses authoritative fiscalized receipt');
test($requests[0][1]['items'][0]['discount-percent']===0&&$requests[0][1]['items'][0]['customizations']===[],'POS cannot apply hidden product discount or modifiers');
$raw['flags']=1<<13;fails(fn()=>E::validate($t->lookup($receipt['external_id'])[0],$plan),'fiscalization failure flag rejected');
$raw['flags']=1<<29;$raw['orderItems'][0]['stockDeduct']=false;fails(fn()=>$t->lookup($receipt['external_id']),'missing stock movement rejected');
$raw['_branchId']=9;fails(fn()=>$t->lookup($receipt['external_id']),'wrong branch rejected');
